func TestPartlyRecoveredGroupStillNeedsRecovery(t *testing.T) {
	project, _, adapter := linkedWorkerSession(t)
	adapter.snapshot.ServerStartedAt = "same-server"
	adapter.snapshot.Panes = adapter.snapshot.Panes[2:3] // Only a Worker has been restored so far.
	if !workerGroupClosed(adapter.snapshot, project, []store.Task{{ID: 1}}) {
		t.Fatal("partial Worker restore was mistaken for a complete group")
	}
	project.LeadPaneID, project.LeadLabel = "", "" // ensureRecoveryWorkspace already created the Lead workspace.
	if !workerGroupClosed(adapter.snapshot, project, []store.Task{{ID: 1}}) {
		t.Fatal("partial Lead workspace hid an incomplete recovery")
	}
	adapter.snapshot.Panes = append(adapter.snapshot.Panes, herdr.Pane{PaneID: "w1:p1", WorkspaceID: project.HerdrWorkspaceID, Label: "posse:shop:lead", Agent: "claude", AgentStatus: "working"})
	if workerGroupClosed(adapter.snapshot, project, []store.Task{{ID: 1}}) {
		t.Fatal("live Lead was treated as a closed group before its identity was persisted")
	}
	adapter.snapshot.Panes = nil // The last Worker failed while the group was closed.
	adapter.snapshot.Workspaces = nil
	if !workerGroupClosed(adapter.snapshot, project, nil) {
		t.Fatal("closed group with no live Workers was not recovered")
	}
	adapter.snapshot.Workspaces = []herdr.Workspace{{WorkspaceID: project.HerdrWorkspaceID}}
	if workerGroupClosed(adapter.snapshot, project, nil) {
		t.Fatal("closing just the Lead pane was mistaken for group close")
	}
}

